//#region src/shared/system-language/index.ts
/**
* How the main process hands the renderer the OS display language.
*
* It travels as a `webPreferences.additionalArguments` entry rather than over
* IPC because `apps/web` picks its language while its i18n module is still
* evaluating — before any `ipcRenderer.invoke` could resolve. `process.argv` is
* one of the few things a sandboxed preload can read synchronously, so the
* value is already there when the bundle asks for it.
*/
var SYSTEM_LANGUAGE_ARG = "--toggl-system-language=";
/**
* Builds the argv entry the renderer parses back out.
*
* Narrowed to `TranslationLocale` rather than `string` so the value can only be
* a catalog key we ship. That is what keeps an argv entry from carrying
* arbitrary text into the renderer, and typing it here rather than relying on
* the one call site puts the guarantee in the codec itself.
*/
var toSystemLanguageArg = (language) => `${SYSTEM_LANGUAGE_ARG}${language}`;
//#endregion
//#region src/main/create-main-window.ts
/**
* The main BrowserWindow. Extracted so a construction test can assert the
* renderer receives the resolved OS display language — the argv codec, preload,
* and web detector each inject the next layer's input, so they would all stay
* green if this wiring were dropped.
*/
var createMainBrowserWindow = (restoredBounds, alwaysOnTop = false) => new electron.BrowserWindow({
	...WINDOW_CONFIG,
	alwaysOnTop,
	...restoredBounds && {
		x: restoredBounds.x,
		y: restoredBounds.y,
		width: restoredBounds.width,
		height: restoredBounds.height
	},
	icon: getResourcePath("icon.png"),
	webPreferences: {
		preload: (0, path.join)(__dirname, "../preload/index.cjs"),
		nodeIntegration: false,
		contextIsolation: true,
		sandbox: true,
		webSecurity: !isDev(),
		additionalArguments: [toSystemLanguageArg(resolveSystemLanguage())]
	},
	show: false
});
