//#region src/main/settings/launch-at-login.ts
var SYSTEM_SETTINGS_URLS = {
	darwin: "x-apple.systempreferences:com.apple.LoginItems-Settings.extension",
	win32: "ms-settings:startupapps"
};
var stripQuotes = (value) => value.replace(/^"(.*)"$/, "$1");
var sameArgs = (a, b) => a.length === b.length && a.every((value, index) => stripQuotes(value) === stripQuotes(b[index]));
var resolveLaunchAtLoginState = (settings, platform, args) => {
	if (platform === "darwin") return {
		enabled: settings.openAtLogin,
		requiresApproval: settings.status === "requires-approval"
	};
	const item = settings.launchItems.find((launchItem) => sameArgs(launchItem.args, args));
	return {
		enabled: settings.openAtLogin && (item?.enabled ?? false),
		requiresApproval: false
	};
};
var getWindowsLaunchOptions = () => {
	if (process.platform !== "win32") return {};
	const exePath = `"${process.execPath}"`;
	if (!isDev() || !process.argv[1]) return { path: exePath };
	return {
		path: exePath,
		args: [path.default.resolve(process.argv[1])]
	};
};
var getLaunchAtLoginState = () => {
	const options = getWindowsLaunchOptions();
	return resolveLaunchAtLoginState(electron.app.getLoginItemSettings(options), process.platform, options.args ?? []);
};
var setLaunchAtLoginEnabled = (enabled) => {
	electron.app.setLoginItemSettings({
		...getWindowsLaunchOptions(),
		openAtLogin: enabled
	});
	return getLaunchAtLoginState();
};
var openLaunchAtLoginSystemSettings = () => {
	const url = SYSTEM_SETTINGS_URLS[process.platform];
	if (url) electron.shell.openExternal(url);
};
