//#region src/main/dev-ipc-fallback.ts
function getIpcDir() {
	return isDev() ? path.default.join(electron.app.getPath("userData"), ".ipc-messages") : null;
}
function drainIpcMessages(dir, handler) {
	let files;
	try {
		files = fs.default.readdirSync(dir).filter((f) => f.endsWith(".json"));
	} catch {
		return;
	}
	for (const file of files) {
		const filePath = path.default.join(dir, file);
		try {
			const content = fs.default.readFileSync(filePath, "utf-8");
			fs.default.unlinkSync(filePath);
			const commandLine = JSON.parse(content);
			electron_log_main.default.info(`Received args from second instance: ${JSON.stringify(commandLine)}`);
			handler(commandLine);
		} catch (e) {
			electron_log_main.default.debug("Failed to process IPC message file %s: %s", file, e);
			try {
				fs.default.unlinkSync(filePath);
			} catch {}
		}
	}
}
/**
* Write IPC message from a second instance that couldn't acquire the lock. Call
* this before `app.quit()` in the second instance.
*/
function writeIpcMessage() {
	const ipcDir = getIpcDir();
	if (!ipcDir) return;
	try {
		fs.default.mkdirSync(ipcDir, { recursive: true });
		const filename = `msg-${process.pid}-${require_training_logic.now()}.json`;
		fs.default.writeFileSync(path.default.join(ipcDir, filename), JSON.stringify(process.argv));
	} catch (e) {
		electron_log_main.default.error("Failed to write IPC message file:", e);
	}
}
/**
* Start watching for IPC messages from second instances. Call this in the first
* (lock-holding) instance.
*/
function startIpcWatcher(handler) {
	const ipcDir = getIpcDir();
	if (!ipcDir) return;
	drainIpcMessages(ipcDir, handler);
	let watcher = null;
	try {
		fs.default.mkdirSync(ipcDir, { recursive: true });
		watcher = fs.default.watch(ipcDir, () => drainIpcMessages(ipcDir, handler));
	} catch (e) {
		electron_log_main.default.warn("fs.watch failed for IPC dir, falling back to polling:", e);
	}
	const ipcPollInterval = setInterval(() => drainIpcMessages(ipcDir, handler), 500);
	electron.app.on("before-quit", () => {
		clearInterval(ipcPollInterval);
		watcher?.close();
	});
}
